/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    int longestUnivaluePath(TreeNode* root) {
        int ans = 0;
        dfs(root, ans);
        return ans;
    }
private:
    int dfs(TreeNode* node, int& ans) {
        if (!node) return 0;
        int left = dfs(node->left, ans);
        int right = dfs(node->right, ans);
        int leftArm = 0, rightArm = 0;
        if (node->left && node->left->val == node->val) leftArm = left + 1;
        if (node->right && node->right->val == node->val) rightArm = right + 1;
        if (leftArm + rightArm > ans) ans = leftArm + rightArm;
        return leftArm > rightArm ? leftArm : rightArm;
    }
};
